from pathlib import Path

def q(v): return "'"+str(v).replace("'","''")+"'"

def article(name, slug, excerpt, facts, fit, notfit):
    content=f'''# {name}: đánh giá thực tế, dữ liệu và bài toán tài chính

## 1. Mở bài — nói thẳng trước khi quan tâm

**{name}** đang được khách hàng quan tâm vì {facts.get('situation','dữ liệu công khai còn cần đối chiếu theo sản phẩm và thời điểm')}. Giá bán hiện tại chưa có một mức áp dụng chung cho mọi sản phẩm; phần giá cụ thể cần lấy theo mã căn, phân khu và ngày cập nhật. Với góc nhìn của người làm nghề **10 năm**, tôi không xem quy mô lớn là lý do đủ để xuống tiền. Câu hỏi đúng là sản phẩm này phù hợp với mục tiêu nào, và người mua phải chấp nhận những rủi ro nào.

## 2. Vị trí và hạ tầng thực tế

Thông tin cần ghi nhớ trước khi đi xem:

- **Vị trí / phạm vi:** {facts['location']}
- **Chủ đầu tư / đơn vị phát triển:** {facts['developer']}
- **Quy mô được công bố:** {facts['scale']}
- **Tiến độ / trạng thái:** {facts['progress']}
- **Mốc di chuyển:** {facts['travel']}

Các mốc thời gian trên bản đồ chỉ có giá trị tham khảo. Khi khảo sát, nên đi vào **07:00–09:00** và **17:00–19:00**, kiểm tra đường vào thực tế, điểm quay đầu, bãi đỗ xe, trường học, bệnh viện và thời gian từ đúng phân khu đến nơi cần đến. Không nên dùng chữ “gần” nếu chưa có **km/phút** đo theo một điểm xuất phát cụ thể.

## 3. Thông tin cơ bản và so sánh lựa chọn

{facts['basic']}

So sánh công bằng phải đặt cùng loại sản phẩm, cùng diện tích, cùng trạng thái pháp lý và cùng thời điểm giá. Với căn hộ, cần so thêm phí quản lý, chỗ đỗ xe, mật độ thang máy và thời gian nhận nhà. Với thấp tầng, cần so thêm mặt tiền, công năng, khả năng kinh doanh, dòng tiền cải tạo và chi phí giữ đất. Những dự án cạnh tranh trực tiếp với {name} không nên được so bằng một câu khẩu hiệu.

## 4. Điểm mạnh có thể kiểm chứng

- {facts['strength1']}
- {facts['strength2']}
- {facts['strength3']}

Điểm mạnh chỉ chuyển thành giá trị sử dụng khi hạng mục đã có tiến độ, quy chế vận hành và chi phí cụ thể. Người mua nên yêu cầu bản vẽ, danh mục bàn giao, thời điểm nghiệm thu và cơ chế xử lý nếu tiến độ thay đổi.

## 5. Hạn chế và rủi ro cần nhìn trước

- Giá bán, chính sách và phí có thể thay đổi theo từng đợt; không lấy mức truyền miệng làm giá chốt.
- Các tiện ích được giới thiệu trong quy hoạch không đồng nghĩa đã hoàn thành hoặc đang vận hành.
- Dự án lớn thường phát triển theo nhiều giai đoạn; thanh khoản và chất lượng sống giữa các phân khu có thể khác nhau.
- Nếu chưa có dữ liệu xác minh về giá thuê, tỷ lệ lấp đầy và chi phí vận hành thì chưa thể cam kết lợi nhuận.

Riêng với {name}, phần cần kiểm tra kỹ nhất là {facts['risk']}.

## 6. Ai nên mua và ai không nên mua?

### Người có thể phù hợp
{fit}

### Người không nên mua lúc này
{notfit} Người cần nhận nhà ngay, cần dòng tiền thuê chắc chắn hoặc mua theo tin đồn nên dừng lại để kiểm tra thêm.

## 7. Bài toán tài chính

Chưa nên lấy giá thuê tốt nhất để tính lợi nhuận. Một bảng tính an toàn cần có: vốn tự có, khoản vay, lãi suất ưu đãi và sau ưu đãi, lịch thanh toán, thuế phí, phí quản lý, nội thất, bảo trì và ít nhất **3–6 tháng** dự phòng dòng tiền. Nếu mua để ở, tổng nghĩa vụ nhà ở nên được đối chiếu với thu nhập ổn định của gia đình. Nếu mua để cho thuê, phải tính tháng trống, chi phí tìm khách và khấu hao nội thất.

Hiện **chưa có dữ liệu xác minh chung** về giá bán áp dụng cho mọi sản phẩm tại {name}; vì vậy chưa thể kết luận tỷ suất cho thuê hay mức tăng giá. Đây là điểm cần ghi rõ, thay vì đưa ra một con số đẹp nhưng không có mã căn và thời điểm.

## 8. Kết luận từ góc nhìn người làm nghề 10 năm

{facts['conclusion']} Kết luận phù hợp nhất ở thời điểm này là: **chỉ nên đi tiếp sau khi khớp đúng tên dự án, phân khu, hồ sơ pháp lý, giá và lịch thanh toán**. Nếu các dữ kiện không khớp, bỏ qua một giao dịch vẫn tốt hơn mua vì sợ lỡ cơ hội.

Gửi mục tiêu, thu nhập, vốn tự có và mã sản phẩm qua Zalo/Hotline **0825 684 139** để Huệ Tây lập file Excel dòng tiền và checklist kiểm tra riêng cho từng căn.''' 
    return (f"article-{slug}", name+': đánh giá thực tế, dữ liệu và tài chính', slug, 'Đánh giá dự án', excerpt, content)

F=[]
def add(*args): F.append(article(*args))
add('Vinhomes Global Gate Hạ Long Xanh','vinhomes-global-gate-ha-long-xanh','Phân tích tên gọi, quy mô, hạ tầng và rủi ro khi nghiên cứu đô thị Hạ Long Xanh.',dict(location='khu vực Tuần Châu, Hạ Long, Hà An và Đông Mai, Quảng Ninh; phạm vi từng phân khu cần đối chiếu',developer='Vinhomes / Vingroup theo dữ liệu công bố',scale='các nguồn công bố nhiều lớp; một số tài liệu nêu khoảng 6.200 ha cho phạm vi Global Gate Hạ Long',progress='đang phát triển theo giai đoạn',travel='cần đo riêng từ Hạ Long, Quảng Yên, cao tốc Hải Phòng–Hạ Long–Vân Đồn và từng phân khu',basic='Tên Hạ Long Xanh thường xuất hiện trong hồ sơ, còn Global Gate Hạ Long là tên thương mại được sử dụng trong truyền thông. Không nên gộp mọi tiện ích của toàn phạm vi vào một sản phẩm.',strength1='Định hướng đô thị, dịch vụ, du lịch, thể thao và không gian xanh–mặt nước ở quy mô lớn.',strength2='Kết nối với hệ sinh thái du lịch Quảng Ninh và các trục giao thông liên vùng.',strength3='Nhiều hạng mục được công bố có số liệu diện tích, nhưng cần phân biệt quy hoạch với hạng mục đã vận hành.',risk='phạm vi dự án, pháp nhân, tiến độ và điều kiện giao dịch của đúng phân khu',conclusion='Đây là hồ sơ phù hợp để nghiên cứu dài hạn, không phù hợp với cách mua dựa trên một con số quy mô hoặc lời hứa tăng giá.'),'Người làm việc tại Quảng Ninh hoặc có tầm nhìn dài hạn, chấp nhận kiểm tra nhiều giai đoạn.','Người cần thanh khoản ngắn hạn, thu nhập thuê cố định hoặc cần nhận nhà ngay.')
add('Vinhomes King Park Bắc Ninh','vinhomes-king-park-bac-ninh','Đánh giá Vinhomes King Park: đô thị 270 ha ven sông Cầu, tổng vốn công bố hơn 41.000 tỷ đồng và những điểm phải kiểm tra.',dict(location='phía Bắc phường Kinh Bắc, Bắc Ninh, hai mặt tiếp giáp sông Cầu và bao quanh bán đảo Hòa Long',developer='Liên danh do Vingroup đại diện theo thông tin khởi công',scale='khoảng 270 ha; mật độ xây dựng dưới 20%; gần 57 ha cây xanh, mặt nước và hơn 70 ha không gian thể thao',progress='khởi công ngày 16/09/2026 theo thông tin báo chí; đang trong giai đoạn triển khai',travel='cần đo từ trung tâm Bắc Ninh, khu công nghiệp, Hà Nội và sân bay Gia Bình sau khi các tuyến kết nối vận hành',basic='Dự án còn được gọi là khu đô thị mới phía Tây Bắc thành phố Bắc Ninh – Khu 1. Tổng vốn đầu tư được công bố hơn 41.000 tỷ đồng; đây là vốn dự án, không phải giá bán từng căn.',strength1='Quy hoạch ven sông với tỷ lệ xây dựng thấp hơn nhiều mô hình đô thị dày đặc.',strength2='Có nhóm nhà liền kề, biệt thự, căn hộ và tiện ích giáo dục, y tế, thương mại, thể thao.',strength3='Vị trí nằm trên các hành lang kinh tế phía Bắc và gần hệ thống công nghiệp Bắc Ninh.',risk='tiến độ thực tế, pháp lý từng sản phẩm, giá mở bán và khả năng vận hành tiện ích',conclusion='King Park có dữ liệu quy hoạch đáng chú ý, nhưng ở thời điểm khởi công chưa thể dùng phối cảnh để kết luận chất lượng sống hay thanh khoản.'),'Gia đình làm việc tại Bắc Ninh, người có kế hoạch ở hoặc nắm giữ dài hạn và chấp nhận chờ tiến độ.','Người dùng đòn bẩy cao, cần thu nhập ngay hoặc mua chỉ vì nghe mức giá truyền miệng.')
add('Vinhomes Ocean Park 1','vinhomes-ocean-park-1','Đánh giá Ocean Park 1: 420 ha, mật độ xây dựng khoảng 19% và bài toán ở thực phía Đông Hà Nội.',dict(location='Gia Lâm, Hà Nội',developer='Vinhomes',scale='420 ha; mật độ xây dựng khoảng 19%; hồ nước mặn 6,1 ha và hồ trung tâm 24,5 ha theo trang dự án',progress='đã có cư dân và nhiều hạng mục vận hành; tình trạng từng tòa cần kiểm tra',travel='khoảng 7 phút đến cầu Vĩnh Tuy theo thông tin dự án; thời gian thực tế thay đổi theo giờ cao điểm',basic='Ocean Park 1 có lợi thế là đô thị đã hình thành cộng đồng, phù hợp để kiểm tra bằng trải nghiệm thật thay vì chỉ nhìn phối cảnh. Giá phải tách theo tòa, tầng, hướng, nội thất và pháp lý căn.',strength1='Mật độ xây dựng thấp theo thông tin dự án và hệ mặt nước lớn tạo không gian mở.',strength2='Đã có cư dân, dịch vụ và hệ thống di chuyển giúp đánh giá chất lượng vận hành thực tế.',strength3='Khoảng cách tới cầu Vĩnh Tuy có thể phù hợp người làm việc ở phía Đông hoặc trung tâm Hà Nội.',risk='ùn tắc tại các cầu và trục vào giờ cao điểm, phí vận hành, chất lượng căn thứ cấp và cạnh tranh nguồn cung',conclusion='Ocean Park 1 phù hợp với người ưu tiên khả năng ở thật và muốn xem tận mắt vận hành; không nên dùng dữ liệu của Ocean Park 2 hoặc 3 để thay thế cho căn tại Ocean Park 1.'),'Gia đình cần ở ngay, người làm việc phía Đông Hà Nội và người muốn kiểm tra căn bằng thực địa.','Người kỳ vọng lợi nhuận cố định hoặc không chấp nhận thời gian di chuyển ngoài giờ thấp điểm.')
add('Vinhomes Ocean Park 2','vinhomes-ocean-park-2-the-empire','Phân tích Ocean Park 2 – The Empire: lựa chọn thấp tầng, tiện ích lớn và rủi ro khi gộp chung với Ocean Park 3.',dict(location='Văn Giang, Hưng Yên theo thông tin công bố về The Empire',developer='Vinhomes',scale='quy mô và cơ cấu sản phẩm cần tách theo hồ sơ The Empire, không dùng số gộp của cả quần thể',progress='nhiều hạng mục đã hình thành; từng dãy và tiện ích cần kiểm tra theo ngày',travel='cần đo từ Hà Nội, cầu Thanh Trì, nút cao tốc và nơi làm việc; thời gian thay đổi mạnh theo giờ',basic='Ocean Park 2 là The Empire, không phải Ocean Park 1. Khi so sánh, cần đặt cùng loại thấp tầng, cùng mặt bằng giá và cùng điều kiện bàn giao; không lấy giá căn hộ Ocean Park 1 làm chuẩn trực tiếp.',strength1='Không gian thấp tầng và các khu vui chơi, thương mại phù hợp nhóm gia đình.',strength2='Có thể khai thác nhu cầu cuối tuần hoặc kinh doanh nếu vị trí và quy chế cho phép.',strength3='Liền kề hành lang phía Đông Hà Nội và Hưng Yên đang phát triển.',risk='chi phí sở hữu thấp tầng, thanh khoản theo mùa, khoảng cách đi làm và khả năng khai thác thực tế',conclusion='The Empire nên được xem là bài toán sản phẩm thấp tầng và vận hành, không phải một cam kết tăng giá chỉ vì nằm trong quần thể Ocean Park.'),'Gia đình có vốn tự có tốt, chấp nhận nắm giữ và cần không gian thấp tầng.','Người chỉ đủ vốn nhờ đòn bẩy cao, cần cho thuê ngay hoặc cần di chuyển trung tâm mỗi ngày.')
add('Vinhomes Ocean Park 3','vinhomes-ocean-park-3-the-crown','Đánh giá Ocean Park 3 – The Crown: 294 ha, vị trí Nghĩa Trụ và bài toán thời gian vận hành.',dict(location='Nghĩa Trụ, Hưng Yên theo thông tin dự án',developer='Vinhomes',scale='khoảng 294 ha theo thông tin công bố',progress='tình trạng từng phân khu và tiện ích cần kiểm tra theo thời điểm',travel='cần đo từ nơi ở đến các trục kết nối Hà Nội–Hưng Yên, đặc biệt ngoài giờ cuối tuần',basic='Ocean Park 3 là The Crown, hợp phần khác Ocean Park 2. Người mua phải xác định rõ mã sản phẩm, phân khu, loại hình và trạng thái bàn giao trước khi so giá.',strength1='Hệ tiện ích vui chơi và mặt nước tạo lợi thế trải nghiệm cho gia đình.',strength2='Quy mô đủ lớn để hình thành nhiều nhóm sản phẩm và dịch vụ.',strength3='Có thể phù hợp người chấp nhận sống ở đô thị vệ tinh phía Đông.',risk='khoảng cách đi làm hàng ngày, thời gian hình thành cộng đồng và mức độ vận hành từng tiện ích',conclusion='The Crown đáng khảo sát theo từng phân khu, nhưng chưa nên đánh đồng mọi sản phẩm trong quần thể với nhau.'),'Gia đình ưu tiên tiện ích nội khu, có lịch làm việc linh hoạt và thời gian nắm giữ dài.','Người cần ở trung tâm, mua để lướt sóng hoặc kỳ vọng giá thuê đã ổn định.')
add('Vinhomes Wonder City Đan Phượng','vinhomes-wonder-city-dan-phuong','Đánh giá Wonder City Đan Phượng: 133,4 ha, 2.250 căn và các mốc pháp lý cần đọc trước khi mua.',dict(location='Đan Phượng, Hà Nội, trên trục Đại lộ Tây Thăng Long',developer='Vinhomes',scale='133,4 ha; mật độ xây dựng 26,7%; quy mô phát triển 2.250 căn',progress='khởi công quý I/2025; trạng thái công bố là đang xây dựng',travel='cần đo từ đúng phân khu đến vành đai, trung tâm hành chính và nơi làm việc; đại lộ mới cần kiểm tra thời gian thực tế',basic='Dữ liệu công bố nêu hình thức sở hữu lâu dài. Đây là điểm cần đối chiếu trong bộ hồ sơ của sản phẩm cụ thể, không thay thế cho hợp đồng mua bán.',strength1='Quy mô vừa đủ để kiểm tra phạm vi, tiến độ và cơ cấu sản phẩm rõ hơn đại đô thị hàng nghìn ha.',strength2='Kết nối với trục Tây Thăng Long và khu vực phía Tây Hà Nội.',strength3='Có tài liệu công bố gồm chủ trương đầu tư, giao đất, quy hoạch 1/500 và bảo lãnh theo trang dự án.',risk='tiến độ bàn giao, giao thông trước khi toàn tuyến hạ tầng hoàn thiện và giá sản phẩm thấp tầng',conclusion='Wonder City phù hợp với người theo dõi phía Tây Hà Nội có kế hoạch dài hạn; cần xem hồ sơ và tiến độ thay vì mua theo kỳ vọng hạ tầng.'),'Gia đình làm việc phía Tây Hà Nội, có kế hoạch ở hoặc giữ tài sản dài hạn.','Người cần nhà vận hành ngay, cần dòng tiền thuê tức thời hoặc phụ thuộc hoàn toàn vào hạ tầng tương lai.')
add('Vinhomes Smart City','vinhomes-smart-city','Phân tích Vinhomes Smart City Tây Mỗ – Đại Mỗ: bài toán căn hộ, giao thông và chi phí vận hành.',dict(location='Tây Mỗ, Đại Mỗ, Nam Từ Liêm, Hà Nội',developer='Vinhomes',scale='đại đô thị căn hộ phía Tây Hà Nội; quy mô và giá cần tách theo phân khu, tòa',progress='đã có cư dân và nhiều tiện ích vận hành; từng tòa cần khảo sát',travel='cần đo đến nơi làm việc, trường học và tuyến metro theo giờ cao điểm; không lấy thời gian lúc vắng xe',basic='Smart City là sản phẩm đô thị căn hộ đã có vận hành, nên bài toán chính là vị trí tòa, phí quản lý, chỗ đỗ xe, chất lượng bàn giao và giá thứ cấp. Không nên chỉ so đơn giá/m².',strength1='Có cộng đồng cư dân và hệ tiện ích nội khu để kiểm tra trực tiếp.',strength2='Phù hợp nhóm khách hàng làm việc tại khu vực Mỹ Đình, Nam Từ Liêm và vành đai phía Tây.',strength3='Nhiều tòa và phân khu tạo lựa chọn ngân sách khác nhau.',risk='ùn tắc tại trục Đại lộ Thăng Long, phí dịch vụ, chỗ đỗ và khác biệt chất lượng giữa các tòa',conclusion='Smart City có ưu thế của một đô thị đã sử dụng, nhưng căn phù hợp phải được chọn theo tòa và nhu cầu thật, không theo tên dự án chung.'),'Người cần căn hộ có vận hành và làm việc phía Tây Hà Nội.','Người cần không gian thấp tầng, yên tĩnh tuyệt đối hoặc kỳ vọng mọi tòa có chất lượng giống nhau.')
add('Vinhomes Vũ Yên Hải Phòng','vinhomes-vu-yen-hai-phong','Đánh giá Vinhomes Vũ Yên – Royal Island: đô thị đảo, sản phẩm thấp tầng và chi phí khai thác cần tính đủ.',dict(location='đảo Vũ Yên, Hải Phòng',developer='Vinhomes',scale='quy mô công bố khoảng 877 ha; cần đọc theo phân khu và sản phẩm',progress='đang phát triển theo giai đoạn',travel='cần đo từ đảo Vũ Yên tới trung tâm Hải Phòng, sân bay Cát Bi và các khu công nghiệp theo giờ thực tế',basic='Royal Island là tên thương mại được dùng cho Vinhomes Vũ Yên. Với sản phẩm thấp tầng, tổng giá và chi phí hoàn thiện quan trọng hơn đơn giá quảng cáo.',strength1='Không gian đảo và hệ sinh thái thấp tầng tạo khác biệt về trải nghiệm.',strength2='Có thể hưởng nhu cầu từ Hải Phòng, chuyên gia và dịch vụ du lịch nếu vận hành đạt kỳ vọng.',strength3='Được phát triển trong bối cảnh Hải Phòng mở rộng hạ tầng và công nghiệp.',risk='kết nối qua cầu, mùa thấp điểm, chi phí vận hành và thời gian hình thành dòng khách',conclusion='Vũ Yên phù hợp với người có chiến lược khai thác dài hạn; không nên dùng công suất du lịch giả định để thay thế doanh thu đã chứng minh.'),'Người có vốn dài hạn, quan tâm thấp tầng và chấp nhận tính chi phí vận hành.','Người cần thanh khoản nhanh, chỉ có thể trả lãi trong thời gian ngắn hoặc cần khách thuê ổn định ngay.')
add('Vinhomes Hóc Môn / Vinhomes Sài Gòn Park','vinhomes-hoc-mon-vinhomes-saigon-park','Phân tích tên gọi Vinhomes Hóc Môn và Sài Gòn Park: hồ sơ, quy mô và rủi ro khi dữ liệu còn đang cập nhật.',dict(location='khu vực Tân Thới Nhì và Tân Hiệp, Hóc Môn, TP. Hồ Chí Minh theo dữ liệu công bố hiện có',developer='cần xác minh pháp nhân và tên thương mại trong hồ sơ giao dịch',scale='nguồn công bố khoảng 1.080 ha; cần xác định phạm vi chính thức',progress='đang cập nhật / cần đối chiếu tiến độ',travel='cần đo Quốc lộ 22, Vành đai 3, cao tốc TP.HCM–Mộc Bài và nơi làm việc theo giờ cao điểm',basic='Nhiều nơi gọi là Vinhomes Hóc Môn hoặc Vinhomes Sài Gòn Park, trong khi hồ sơ có thể dùng tên Khu đô thị Đại học Quốc tế. Tên thương mại không đủ để kết luận đã được mở bán.',strength1='Nếu đúng định hướng đô thị tri thức, nhu cầu giáo dục, nghiên cứu và dịch vụ có thể tạo lực cầu dài hạn.',strength2='Nằm trên hành lang phía Tây Bắc TP.HCM.',strength3='Quy mô lớn cho phép phát triển nhiều chức năng nếu hồ sơ được phê duyệt và triển khai đúng.',risk='tên pháp lý, điều kiện mở bán, quy hoạch chi tiết, sản phẩm và giá chưa có dữ liệu xác minh chung',conclusion='Đây là dự án cần kiểm tra giấy tờ trước tiên. Người mua không nên đặt cọc dựa trên tên gọi, bản đồ lan truyền hoặc bảng giá không có pháp nhân xác nhận.'),'Người có liên hệ thực tế với Tây Bắc TP.HCM và chấp nhận chờ dữ liệu chính thức.','Người cần mua ngay, ngại rủi ro tên gọi hoặc chỉ dựa vào tin môi giới.')
add('Vinhomes Green Paradise Cần Giờ','vinhomes-green-paradise-can-gio','Đánh giá Green Paradise Cần Giờ: 2.870 ha, đô thị biển và bài toán hạ tầng–môi trường cần kiểm chứng.',dict(location='Long Hòa và Cần Thạnh, Cần Giờ, TP. Hồ Chí Minh',developer='Vinhomes',scale='2.870 ha; mật độ xây dựng khoảng 23%; 4 khu phát triển',progress='khởi công quý II/2025; đang xây dựng theo trang dự án',travel='cần đo từ trung tâm TP.HCM, Nhà Bè, sân bay Long Thành và các tuyến kết nối dự kiến; thời gian hiện tại không đồng nghĩa thời gian sau khi hạ tầng hoàn thành',basic='Tên pháp lý và tên thương mại cần được dùng song song. Quy mô lớn tạo nhiều lớp sản phẩm nhưng cũng khiến tiến độ, môi trường, giao thông và vận hành phải được đánh giá theo từng khu.',strength1='Đô thị biển quy mô lớn, có định hướng ở, du lịch, dịch vụ và giải trí.',strength2='Trang dự án công bố 4 khu, mật độ xây dựng khoảng 23% và hình thức sở hữu lâu dài.',strength3='Có bộ tài liệu dự án và pháp lý để người mua yêu cầu đối chiếu.',risk='tác động môi trường, hạ tầng kết nối, thời gian hoàn thiện các hạng mục lớn và điều kiện mở bán',conclusion='Green Paradise phù hợp với người có tầm nhìn dài hạn và chấp nhận giai đoạn phát triển; không nên coi tiện ích quy hoạch là dòng tiền đã vận hành.'),'Người nghiên cứu đô thị biển dài hạn, có vốn tự có và không cần nhận nhà ngay.','Người cần dòng tiền thuê tức thời, vốn mỏng hoặc không chấp nhận rủi ro hạ tầng.')
add('Vinhomes Green City Hậu Nghĩa','vinhomes-green-city-hau-nghia','Đánh giá Green City Hậu Nghĩa: 197,22 ha, 4.572 căn và khoảng cách thực tế tới Tây Bắc TP.HCM.',dict(location='khu vực Hậu Nghĩa, Đức Hòa, Long An; nay thuộc vùng đô thị phía Tây Bắc TP.HCM',developer='Vinhomes',scale='197,22 ha; mật độ xây dựng 60%; quy mô 4.572 căn; 5 khu phát triển',progress='khởi công năm 2025; đang xây dựng',travel='khoảng 15 phút từ trung tâm Tây Bắc TP.HCM theo thông tin dự án, hơn 60 phút tới Tân Sơn Nhất và khoảng 40 phút tới Mộc Bài; cần đo theo giờ',basic='Green City có cơ cấu nhà phố, shophouse và biệt thự. Tỷ lệ xây dựng 60% cần đọc cùng cơ cấu sản phẩm và diện tích cây xanh, không nên tự suy ra chất lượng sống chỉ từ một tỷ lệ.',strength1='Quy mô vừa đủ để hình thành đô thị đa chức năng ở cửa ngõ Tây Bắc.',strength2='Có dữ liệu khoảng cách và các phân khu được công bố rõ hơn nhiều dự án mới.',strength3='Có thể hưởng nhu cầu ở và kinh doanh từ khu công nghiệp Đức Hòa, Xuyên Á, Tân Đức nếu kết nối vận hành tốt.',risk='giao thông liên vùng, mức giá so với thu nhập khu vực, khả năng lấp đầy thương mại và chi phí sở hữu thấp tầng',conclusion='Green City nên được phân tích như bài toán ở–kinh doanh gắn với Tây Bắc TP.HCM, không chỉ như một câu chuyện hạ tầng tương lai.'),'Gia đình và hộ kinh doanh có liên hệ với Đức Hòa, Tây Bắc TP.HCM, có kế hoạch ở hoặc khai thác dài hạn.','Người làm việc sâu trong nội đô, cần thanh khoản ngắn hoặc chỉ dựa vào kỳ vọng cao tốc.')
add('Vinhomes Olympic / Global Sportia','vinhomes-olympic-global-sportia','Phân tích Vinhomes Olympic: cần phân biệt phạm vi nghiên cứu quy hoạch 16.000 ha với dự án có sản phẩm mở bán.',dict(location='khu vực phía Nam Hà Nội; phạm vi nghiên cứu quy hoạch thể thao liên quan nhiều xã, phường',developer='Vingroup/Vinhomes theo thông tin công bố, cần xác minh pháp nhân từng khu',scale='phạm vi nghiên cứu hơn 16.000 ha; khu đô thị khoảng 9.171 ha theo thông tin báo chí về quy hoạch, không phải diện tích một sản phẩm mở bán',progress='quy hoạch và triển khai hạ tầng theo từng phần; chưa thể coi toàn bộ đã mở bán',travel='cần đo từ Ngọc Hồi, Thanh Trì, các trục vành đai và nơi làm việc; thời gian phụ thuộc từng khu',basic='Tên Vinhomes Olympic và Global Sportia đang được dùng song song trong thông tin thị trường. Phạm vi nghiên cứu quy hoạch cần tách khỏi pháp nhân, ranh giới và sản phẩm cụ thể.',strength1='Định hướng thể thao và hạ tầng quy mô lớn có thể tạo lực hút mới cho phía Nam Hà Nội.',strength2='Nếu triển khai đúng, hệ thống sân bãi và không gian công cộng tạo khác biệt so với khu ở thông thường.',strength3='Có câu chuyện quy hoạch vùng để nghiên cứu dài hạn.',risk='ranh giới dự án, mốc phê duyệt, sản phẩm, giá và điều kiện mở bán chưa có dữ liệu chung để chốt',conclusion='Đây là bài cần thận trọng nhất trong danh sách. Người mua chỉ nên làm việc với hồ sơ của một sản phẩm cụ thể, không đặt cọc dựa trên tên Olympic hoặc con số 16.000 ha.'),'Người nghiên cứu quy hoạch dài hạn, không cần giao dịch ngay và biết kiểm tra pháp lý.','Người cần mua căn cụ thể trong thời gian ngắn, kỳ vọng giá tăng theo tin quy hoạch hoặc cần cam kết lợi nhuận.')

vals=[]
for id_,title,slug,cat,excerpt,content in F:
    vals.append(f"({q(id_)},{q(title)},{q(slug)},{q(cat)},{q(excerpt)},{q(content)},CURRENT_DATE,'published')")
sql="insert into public.articles(id,title,slug,category,excerpt,content,published_at,status) values\n"+",\n".join(vals)+"\non conflict (slug) do update set title=excluded.title,category=excluded.category,excerpt=excluded.excerpt,content=excluded.content,published_at=excluded.published_at,status='published';"
Path('/home/ubuntu/huetay-migrate/scripts/vinhomes-articles.sql').write_text(sql)
